CREATE TABLE IF NOT EXISTS `monitoring_jenkins_executions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT, `request_id` varchar(64) NOT NULL, `mode` enum('preview','apply') NOT NULL, `mr_iid` int unsigned NOT NULL, `commit_sha` char(40) NOT NULL, `application_id` varchar(63) NOT NULL, `queue_id` bigint unsigned NOT NULL, `build_number` int unsigned DEFAULT NULL, `status` varchar(32) NOT NULL, `diff_text` mediumtext DEFAULT NULL, `requested_by_user_id` bigint unsigned NOT NULL, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `finished_at` datetime DEFAULT NULL, PRIMARY KEY (`id`), KEY `idx_monitoring_jenkins_request` (`request_id`,`created_at`), CONSTRAINT `fk_monitoring_jenkins_request` FOREIGN KEY (`request_id`) REFERENCES `monitoring_requests` (`request_id`), CONSTRAINT `fk_monitoring_jenkins_requester` FOREIGN KEY (`requested_by_user_id`) REFERENCES `users` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
